<?php
/* FieldPlx automation execution engine. PHP 7.2 compatible. */
function faeTable(PDO $pdo,$t){static $c=array();if(isset($c[$t]))return $c[$t];$s=$pdo->prepare("SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=:t");$s->execute(array(':t'=>$t));return $c[$t]=((int)$s->fetchColumn()>0);}
function faeColumn(PDO $pdo,$t,$col){static $c=array();$k=$t.'.'.$col;if(isset($c[$k]))return $c[$k];$s=$pdo->prepare("SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=:t AND COLUMN_NAME=:c");$s->execute(array(':t'=>$t,':c'=>$col));return $c[$k]=((int)$s->fetchColumn()>0);}
function faeDecode($v){$x=json_decode((string)$v,true);return is_array($x)?$x:array();}
function faeStatus($v){return strtolower(str_replace(' ','_',trim((string)$v)));}
function faeEntityConfig($key){if($key==='quote')return array('table'=>'quotes','no'=>array('quote_no'),'line_tables'=>array('quote_line_items'),'line_fk'=>'quote_id');if($key==='invoice')return array('table'=>'invoices','no'=>array('invoice_no','invoice_number'),'line_tables'=>array('invoice_line_items'),'line_fk'=>'invoice_id');if($key==='request')return array('table'=>'service_requests','no'=>array('request_no'),'line_tables'=>array('request_line_items'),'line_fk'=>'request_id');return null;}
function faeTenantTimezone(PDO $pdo,$tenant){$tz='UTC';try{$s=$pdo->prepare("SELECT timezone FROM tenants WHERE id=:t LIMIT 1");$s->execute(array(':t'=>$tenant));$v=trim((string)$s->fetchColumn());if($v!==''&&in_array($v,timezone_identifiers_list(),true))$tz=$v;}catch(Throwable $e){}return $tz;}
function faeDueAt($anchor,$relation,$offset,$timezone){$tz=new DateTimeZone($timezone);$a=new DateTime((string)$anchor,$tz);$a->setTime((int)$a->format('H'),(int)$a->format('i'),(int)$a->format('s'));$n=max(0,(int)$offset);if($relation==='before'&&$n)$a->modify('-'.$n.' days');elseif($relation==='after'&&$n)$a->modify('+'.$n.' days');if(strlen((string)$anchor)<=10)$a->setTime(9,0,0);return $a;}
function faeGetClient(PDO $pdo,$tenant,$clientId){if($clientId<=0||!faeTable($pdo,'clients'))return array();$cols=array('id','display_name');foreach(array('email','phone') as $x)if(faeColumn($pdo,'clients',$x))$cols[]=$x;$s=$pdo->prepare("SELECT ".implode(',',$cols)." FROM clients WHERE id=:id AND tenant_id=:t LIMIT 1");$s->execute(array(':id'=>$clientId,':t'=>$tenant));return $s->fetch(PDO::FETCH_ASSOC)?:array();}
function faeCompany(PDO $pdo,$tenant){try{$s=$pdo->prepare("SELECT display_name FROM tenants WHERE id=:t LIMIT 1");$s->execute(array(':t'=>$tenant));return (string)$s->fetchColumn();}catch(Throwable $e){return 'FieldPlx';}}
function faeDocumentNo(PDO $pdo,$cfg,$row){foreach($cfg['no'] as $c)if(array_key_exists($c,$row)&&trim((string)$row[$c])!=='')return (string)$row[$c];return '#'.(int)$row['id'];}
function faeMerge($text,$vars){foreach($vars as $k=>$v)$text=str_replace('{{'.$k.'}}',(string)$v,(string)$text);return $text;}
function faeConditionPass(PDO $pdo,$tenant,$entity,$row,$condition){$key=(string)$condition['condition_key'];$op=(string)$condition['operator_key'];if($key==='status'){$actual=faeStatus(isset($row['status'])?$row['status']:'');$wanted=faeStatus(isset($condition['value_text'])?$condition['value_text']:'');return $op==='is_not'?$actual!==$wanted:$actual===$wanted;}$clientId=(int)(isset($row['client_id'])?$row['client_id']:0);if($key==='client_tag'){$tag=(int)$condition['value_id'];$has=false;if($tag>0&&$clientId>0&&faeTable($pdo,'client_tag_assignments')){$s=$pdo->prepare("SELECT 1 FROM client_tag_assignments WHERE tenant_id=:t AND client_id=:c AND tag_id=:tag LIMIT 1");$s->execute(array(':t'=>$tenant,':c'=>$clientId,':tag'=>$tag));$has=(bool)$s->fetchColumn();}return $op==='not_include'?!$has:$has;}if($key==='line_item'){$pid=(int)$condition['value_id'];$cfg=faeEntityConfig($entity);$has=false;if($pid>0&&$cfg){if($entity==='request'&&faeColumn($pdo,'service_requests','product_service_id')){$has=(int)(isset($row['product_service_id'])?$row['product_service_id']:0)===$pid;}else{foreach($cfg['line_tables'] as $lt){if(!faeTable($pdo,$lt)||!faeColumn($pdo,$lt,'product_service_id'))continue;$s=$pdo->prepare("SELECT 1 FROM `$lt` WHERE `".$cfg['line_fk']."`=:id AND product_service_id=:p LIMIT 1");$s->execute(array(':id'=>(int)$row['id'],':p'=>$pid));if($s->fetchColumn()){$has=true;break;}}}}return $op==='not_include'?!$has:$has;}return true;}
function faeNotify(PDO $pdo,$tenant,$entity,$row,$cfg,$actionConfig){$client=faeGetClient($pdo,$tenant,(int)$row['client_id']);$channel=isset($actionConfig['channel'])?(string)$actionConfig['channel']:'email';$company=faeCompany($pdo,$tenant);$ec=faeEntityConfig($entity);$vars=array('customer_name'=>isset($client['display_name'])?$client['display_name']:'Customer','company_name'=>$company,'document_no'=>faeDocumentNo($pdo,$ec,$row));$subject=faeMerge(isset($actionConfig['subject'])?$actionConfig['subject']:'FieldPlx notification',$vars);$message=faeMerge(isset($actionConfig['message'])?$actionConfig['message']:'',$vars);if($channel==='in_app'){if(!faeTable($pdo,'in_app_notifications'))throw new RuntimeException('In-app notifications table is not installed.');$userId=faeColumn($pdo,'clients','tenant_user_id')?(int)(isset($client['tenant_user_id'])?$client['tenant_user_id']:0):0;if($userId<=0)throw new RuntimeException('Customer has no linked portal user for in-app notification.');$s=$pdo->prepare("INSERT INTO in_app_notifications(tenant_id,user_id,title,message,related_type,related_id,icon_name,is_read) VALUES(:t,:u,:title,:m,:rt,:rid,'bell',0)");$s->execute(array(':t'=>$tenant,':u'=>$userId,':title'=>$subject,':m'=>$message,':rt'=>$entity,':rid'=>(int)$row['id']));return array('channel'=>'in_app','sent'=>1);}$email=trim((string)(isset($client['email'])?$client['email']:''));if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Customer has no valid email address.');if(!function_exists('fieldplxSendPlatformMail'))throw new RuntimeException('Platform SMTP helper is unavailable.');$html='<div style="font-family:Arial,Helvetica,sans-serif;max-width:620px;margin:auto;color:#173644">'.nl2br(htmlspecialchars($message,ENT_QUOTES,'UTF-8')).'</div>';fieldplxSendPlatformMail($pdo,$email,$subject,$html);return array('channel'=>'email','sent'=>1,'to'=>$email);}
function faeAddTag(PDO $pdo,$tenant,$row,$tagId){$clientId=(int)$row['client_id'];if($clientId<=0||$tagId<=0)throw new RuntimeException('Customer tag action is incomplete.');if(!faeTable($pdo,'client_tag_assignments'))throw new RuntimeException('Client tag assignments table is not installed.');$cols='tenant_id,client_id,tag_id';$vals=':t,:c,:tag';$args=array(':t'=>$tenant,':c'=>$clientId,':tag'=>$tagId);if(faeColumn($pdo,'client_tag_assignments','created_by')){$cols.=',created_by';$vals.=',NULL';}$s=$pdo->prepare("INSERT IGNORE INTO client_tag_assignments($cols) VALUES($vals)");$s->execute($args);return array('tag_id'=>$tagId,'assigned'=>1);}
function faeUpdateStatus(PDO $pdo,$tenant,$entity,$row,$status){$cfg=faeEntityConfig($entity);if(!$cfg)throw new RuntimeException('Unsupported entity status action.');$status=faeStatus($status);$set='status=:s';if($entity==='quote'&&$status==='sent'&&faeColumn($pdo,'quotes','sent_at'))$set.=',sent_at=COALESCE(sent_at,NOW())';if($entity==='quote'&&$status==='approved'&&faeColumn($pdo,'quotes','approved_at'))$set.=',approved_at=COALESCE(approved_at,NOW())';if(faeColumn($pdo,$cfg['table'],'updated_at'))$set.=',updated_at=NOW()';$s=$pdo->prepare("UPDATE `".$cfg['table']."` SET $set WHERE id=:id AND tenant_id=:t");$s->execute(array(':s'=>$status,':id'=>(int)$row['id'],':t'=>$tenant));return array('status'=>$status,'updated'=>1);}
function faeExecuteActions(PDO $pdo,$tenant,$entity,$row,$actions){$out=array();foreach($actions as $a){$key=(string)$a['action_key'];if($key==='notify')$out[]=faeNotify($pdo,$tenant,$entity,$row,faeEntityConfig($entity),faeDecode($a['config_json']));elseif($key==='add_tag')$out[]=faeAddTag($pdo,$tenant,$row,(int)$a['value_id']);elseif($key==='update_status')$out[]=faeUpdateStatus($pdo,$tenant,$entity,$row,(string)$a['value_text']);}return $out;}
function fieldplxRunAutomations(PDO $pdo,$limit=250){$stats=array('rules'=>0,'candidates'=>0,'success'=>0,'failed'=>0,'skipped'=>0);if(!faeTable($pdo,'tenant_automations'))return $stats;$sql="SELECT a.*,t.trigger_key,t.source_date_column,e.source_table FROM tenant_automations a JOIN platform_automation_triggers t ON t.id=a.trigger_id JOIN platform_automation_entities e ON e.entity_key=a.entity_key WHERE a.is_active=1 AND t.is_active=1 AND t.is_visible=1 AND e.is_active=1 AND e.is_visible=1 ORDER BY a.id";$rules=$pdo->query($sql)->fetchAll(PDO::FETCH_ASSOC);foreach($rules as $rule){$stats['rules']++;$tenant=(int)$rule['tenant_id'];$entity=(string)$rule['entity_key'];$table=(string)$rule['source_table'];$dateCol=(string)$rule['source_date_column'];if(!faeTable($pdo,$table)||!faeColumn($pdo,$table,$dateCol))continue;$cols=array('id','tenant_id');foreach(array('client_id','status','branch_id','product_service_id') as $c)if(faeColumn($pdo,$table,$c))$cols[]=$c;foreach((faeEntityConfig($entity)?faeEntityConfig($entity)['no']:array()) as $c)if(faeColumn($pdo,$table,$c))$cols[]=$c;$cols[]=$dateCol.' AS trigger_anchor';$s=$pdo->prepare("SELECT ".implode(',',array_unique($cols))." FROM `$table` WHERE tenant_id=:t AND `$dateCol` IS NOT NULL ORDER BY `$dateCol` DESC LIMIT 1000");$s->execute(array(':t'=>$tenant));$rows=$s->fetchAll(PDO::FETCH_ASSOC);$tz=faeTenantTimezone($pdo,$tenant);$now=new DateTime('now',new DateTimeZone($tz));$cs=$pdo->prepare("SELECT c.*,m.condition_key FROM tenant_automation_conditions c JOIN platform_automation_conditions m ON m.id=c.condition_id WHERE c.automation_id=:a AND c.tenant_id=:t ORDER BY c.sort_order,c.id");$cs->execute(array(':a'=>$rule['id'],':t'=>$tenant));$conds=$cs->fetchAll(PDO::FETCH_ASSOC);$as=$pdo->prepare("SELECT x.*,m.action_key FROM tenant_automation_actions x JOIN platform_automation_actions m ON m.id=x.action_id WHERE x.automation_id=:a AND x.tenant_id=:t ORDER BY x.sort_order,x.id");$as->execute(array(':a'=>$rule['id'],':t'=>$tenant));$actions=$as->fetchAll(PDO::FETCH_ASSOC);foreach($rows as $row){if($stats['candidates']>=$limit)break 2;$due=faeDueAt($row['trigger_anchor'],$rule['trigger_relation'],$rule['trigger_offset_value'],$tz);if($due>$now)continue;$stats['candidates']++;$key=hash('sha256',$tenant.'|'.$rule['id'].'|'.$entity.'|'.$row['id'].'|'.$row['trigger_anchor'].'|'.$due->format('Y-m-d H:i:s'));$chk=$pdo->prepare("SELECT status FROM tenant_automation_runs WHERE idempotency_key=:k LIMIT 1");$chk->execute(array(':k'=>$key));if($chk->fetchColumn()){continue;}$pass=true;foreach($conds as $c){if(!faeConditionPass($pdo,$tenant,$entity,$row,$c)){$pass=false;break;}}$ins=$pdo->prepare("INSERT INTO tenant_automation_runs(tenant_id,automation_id,entity_key,entity_id,client_id,trigger_anchor_at,scheduled_for,status,idempotency_key,started_at) VALUES(:t,:a,:e,:eid,:c,:anchor,:due,:status,:k,NOW())");$ins->execute(array(':t'=>$tenant,':a'=>$rule['id'],':e'=>$entity,':eid'=>$row['id'],':c'=>isset($row['client_id'])?(int)$row['client_id']:null,':anchor'=>$row['trigger_anchor'],':due'=>$due->format('Y-m-d H:i:s'),':status'=>$pass?'running':'skipped',':k'=>$key));$runId=(int)$pdo->lastInsertId();if(!$pass){$pdo->prepare("UPDATE tenant_automation_runs SET finished_at=NOW(),action_result_json=:r WHERE id=:id")->execute(array(':r'=>'{"reason":"conditions_not_met"}',':id'=>$runId));$stats['skipped']++;continue;}try{$pdo->beginTransaction();$result=faeExecuteActions($pdo,$tenant,$entity,$row,$actions);$pdo->prepare("UPDATE tenant_automation_runs SET status='success',action_result_json=:r,finished_at=NOW() WHERE id=:id")->execute(array(':r'=>json_encode($result,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),':id'=>$runId));$pdo->commit();$stats['success']++;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$pdo->prepare("UPDATE tenant_automation_runs SET status='failed',error_message=:m,finished_at=NOW() WHERE id=:id")->execute(array(':m'=>substr($e->getMessage(),0,65000),':id'=>$runId));$stats['failed']++;error_log('FieldPlx automation run '.$runId.': '.$e->getMessage());}}}return $stats;}
